<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>muse-wonder-full-1.0</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #0b0e13; font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; color: #e8edf4; }
  #app { position: fixed; inset: 0; }
  canvas { display: block; }
  #brand { position: fixed; top: 12px; left: 14px; z-index: 20; font-size: 15px; font-weight: 650; letter-spacing: .02em;
           background: rgba(10,14,20,.55); padding: 7px 12px; border-radius: 9px; border: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(6px); }
  #hud { position: fixed; top: 52px; left: 14px; z-index: 20; font-size: 12px; line-height: 1.5; color: #c9d4e3;
         background: rgba(10,14,20,.5); padding: 7px 11px; border-radius: 9px; border: 1px solid rgba(255,255,255,.1); backdrop-filter: blur(6px); min-width: 168px; }
  #hud b { color: #fff; font-weight: 650; }
