  /* ---- playback / control bar ---- */
  #bar { position: fixed; left: 50%; transform: translateX(-50%); bottom: 12px; z-index: 30; display: flex; align-items: center; gap: 14px; flex-wrap: wrap; justify-content: center;
         background: rgba(10,14,20,.72); border: 1px solid rgba(255,255,255,.13); border-radius: 14px; padding: 9px 14px; backdrop-filter: blur(8px); max-width: min(96vw, 980px); }
  .grp { display: flex; align-items: center; gap: 5px; }
  .grp .lab { font-size: 10px; text-transform: uppercase; letter-spacing: .08em; color: #8fa1b8; margin-right: 3px; }
  button { appearance: none; border: 1px solid rgba(255,255,255,.16); background: #1c2534; color: #e8edf4; font: inherit; font-size: 12.5px;
           padding: 6px 11px; border-radius: 8px; cursor: pointer; white-space: nowrap; }
  button:hover { background: #283449; }
  button:focus-visible { outline: 2px solid #6cb2ff; outline-offset: 1px; }
  button.on { background: #2f6fd0; border-color: #5b97e8; color: #fff; }
  button.primary { background: #2f6fd0; border-color: #5b97e8; font-weight: 650; }
