          padding: 5px 9px; border-radius: 8px; border: 1px solid rgba(255,255,255,.08); }
  /* ---- settings panel ---- */
  #panel { position: fixed; top: 12px; right: 12px; z-index: 30; width: 270px; max-height: calc(100vh - 110px); overflow-y: auto;
           background: rgba(10,14,20,.78); border: 1px solid rgba(255,255,255,.13); border-radius: 14px; padding: 12px 13px 13px; backdrop-filter: blur(8px); }
  #panel.hidden { display: none; }
  #panel h2 { font-size: 13px; font-weight: 700; letter-spacing: .04em; margin-bottom: 2px; }
  #panel p.note { font-size: 11px; color: #93a5bd; margin-bottom: 10px; line-height: 1.45; }
  .sec { font-size: 10px; text-transform: uppercase; letter-spacing: .09em; color: #7f93ad; margin: 11px 0 5px; border-top: 1px solid rgba(255,255,255,.09); padding-top: 8px; }
  .sec:first-of-type { border-top: none; padding-top: 0; margin-top: 2px; }
  .row { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 4px 0; }
  .row label { font-size: 12px; color: #cdd9ea; flex: 1; }
  .row input { width: 86px; background: #131c2b; color: #fff; border: 1px solid rgba(255,255,255,.18); border-radius: 7px; padding: 5px 7px; font: inherit; font-size: 12.5px; text-align: right; }
  .row input:focus { outline: 2px solid #6cb2ff; outline-offset: 0; border-color: transparent; }
  #panel .actions { display: flex; gap: 7px; margin-top: 13px; }
  #panel .actions button { flex: 1; }
  @media (max-width: 720px) { #panel { width: 238px; } #hint { display: none; } #hud { display: none; } }
</style>
<script type="importmap">
{
