</div>
<div id="hint">Space: pause/play · Orbit: drag to look, wheel to zoom</div>

<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import * as CANNON from 'cannon-es';

/* ================= deterministic utilities (visuals only) ================= */
function mulberry32(seed){ let a = seed >>> 0; return function(){ a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const clamp = (v,a,b)=>Math.max(a,Math.min(b,v));
const smooth01 = t=>{ t = clamp(t,0,1); return t*t*(3-2*t); };

/* ================= mandatory defaults + settings fields ================= */
const FIELDS = [
  { sec:'Car' },
  { id:'speed',          label:'Impact speed (m/s)', def:22,    min:2,    max:60,   step:0.5 },
  { id:'carMass',        label:'Car mass (kg)',      def:1250,  min:300,  max:4000, step:10 },
  { id:'carLength',      label:'Car length (m)',     def:4.2,   min:2.6,  max:6.5,  step:0.1 },
  { id:'carWidth',       label:'Car width (m)',      def:1.8,   min:1.2,  max:2.6,  step:0.05 },
  { id:'carHeight',      label:'Car height (m)',     def:1.45,  min:0.9,  max:2.4,  step:0.05 },
  { sec:'Wall & bricks' },
  { id:'wallCols',       label:'Wall columns',       def:12,    min:4,    max:26,   step:1, int:true },
  { id:'wallRows',       label:'Wall rows',          def:8,     min:2,    max:18,   step:1, int:true },
  { id:'wallDepth',      label:'Wall depth (bricks)',def:2,     min:1,    max:5,    step:1, int:true },
  { id:'brickMass',      label:'Brick mass (kg)',    def:2.5,   min:0.3,  max:25,   step:0.1 },
  { id:'brickW',         label:'Brick width (m)',    def:0.50,  min:0.18, max:1.1,  step:0.02 },
  { id:'brickH',         label:'Brick height (m)',   def:0.24,  min:0.08, max:0.6,  step:0.02 },
  { id:'brickD',         label:'Brick depth (m)',    def:0.20,  min:0.08, max:0.6,  step:0.02 },
  { sec:'Physics & track' },
  { id:'gravity',        label:'Gravity (m/s²)',     def:9.81,  min:0.5,  max:30,   step:0.1 },
  { id:'brickFriction',  label:'Brick friction',     def:0.72,  min:0,    max:1.5,  step:0.02 },
  { id:'brickRest',      label:'Brick restitution',  def:0.18,  min:0,    max:0.95, step:0.02 },
  { id:'groundFriction', label:'Ground friction',    def:0.85,  min:0,    max:1.5,  step:0.02 },
  { id:'trackLength',    label:'Track length (m)',   def:40,    min:24,   max:90,   step:1 },
];
const DEFAULTS = {}; FIELDS.forEach(f=>{ if(f.id) DEFAULTS[f.id] = f.def; });

const fieldsEl = document.getElementById('fields');
const inputs = {};
for (const f of FIELDS){
  if (f.sec){ const d = document.createElement('div'); d.className='sec'; d.textContent=f.sec; fieldsEl.appendChild(d); continue; }
  const row = document.createElement('div'); row.className='row';
  const lab = document.createElement('label'); lab.htmlFor = 'in_'+f.id; lab.textContent = f.label;
  const inp = document.createElement('input');
  inp.type='number'; inp.id='in_'+f.id; inp.value=String(f.def); inp.min=f.min; inp.max=f.max; inp.step=f.step; inp.inputMode='decimal';
  row.append(lab, inp); fieldsEl.appendChild(row); inputs[f.id] = { f, inp };
}
function readSettings(){
  const s = {};
  for (const id in inputs){
    const { f, inp } = inputs[id];
    let v = parseFloat(inp.value);
    if (!Number.isFinite(v)) v = f.def;
    v = clamp(v, f.min, f.max);
    if (f.int) v = Math.round(v);
    inp.value = String(v);
    s[id] = v;
  }
  return s;
}
function fillSettings(s){ for (const id in inputs) inputs[id].inp.value = String(s[id]); }

/* ================= renderer / scene / lights ================= */
const app = document.getElementById('app');
const renderer = new THREE.WebGLRenderer({ antialias:true, powerPreference:'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9ec7e8);
scene.fog = new THREE.Fog(0xbdd7ee, 70, 260);

const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

const camera = new THREE.PerspectiveCamera(55, innerWidth/innerHeight, 0.1, 500);
camera.position.set(-8, 9, 17);

const hemi = new THREE.HemisphereLight(0xcfe6ff, 0x5a6a52, 0.55);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff3dd, 2.6);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.03;
sun.shadow.radius = 2;
scene.add(sun); scene.add(sun.target);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true; controls.dampingFactor = 0.08;
controls.maxPolarAngle = Math.PI * 0.495; controls.minDistance = 3; controls.maxDistance = 90;
controls.enabled = false;

/* ================= shared materials / procedural textures ================= */
function makeNoiseTexture(base, specks, n, seed, size=256){
  const rng = mulberry32(seed);
  const c = document.createElement('canvas'); c.width = c.height = size;
  const g = c.getContext('2d'); g.fillStyle = base; g.fillRect(0,0,size,size);
  for (let i=0;i<n;i++){
    g.fillStyle = specks[Math.floor(rng()*specks.length)];
    g.globalAlpha = 0.12 + rng()*0.3;
    const s = 1 + rng()*2.4;
    g.fillRect(rng()*size, rng()*size, s, s);
  }
  g.globalAlpha = 1;
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 4; t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const asphaltTex = makeNoiseTexture('#35383c', ['#45494f','#26282c','#555a61','#1f2125'], 5200, 101);
const brickTex   = makeNoiseTexture('#a5573f', ['#8c4330','#b96a4c','#7d3a2b','#c07a5c'], 2200, 202, 128);
const grassTex   = makeNoiseTexture('#4d7d3a', ['#5d9047','#3f6b2f','#6aa050'], 4200, 303);
grassTex.repeat.set(30, 18);

const MAT = {
  paint:     new THREE.MeshPhysicalMaterial({ color:0x2456c8, metalness:0.65, roughness:0.32, clearcoat:1.0, clearcoatRoughness:0.08, envMapIntensity:1.25 }),
  paintDark: new THREE.MeshStandardMaterial({ color:0x20242b, metalness:0.25, roughness:0.62, envMapIntensity:0.7 }),
  interior:  new THREE.MeshStandardMaterial({ color:0x161a20, metalness:0.3, roughness:0.45, envMapIntensity:0.8 }),
  glass:     new THREE.MeshPhysicalMaterial({ color:0xbfe0ee, metalness:0, roughness:0.06, transmission:0.88, thickness:0.03, ior:1.5, envMapIntensity:1.4, transparent:true, opacity:0.96 }),
  tire:      new THREE.MeshStandardMaterial({ color:0x141414, metalness:0.05, roughness:0.95 }),
  rim:       new THREE.MeshStandardMaterial({ color:0xd7dbe0, metalness:1.0, roughness:0.28, envMapIntensity:1.3 }),
  chrome:    new THREE.MeshStandardMaterial({ color:0xe8ecf0, metalness:1.0, roughness:0.15, envMapIntensity:1.4 }),
  headlight: new THREE.MeshStandardMaterial({ color:0xfff6d8, emissive:0xffeeb0, emissiveIntensity:1.6, metalness:0.4, roughness:0.25 }),
  taillight: new THREE.MeshStandardMaterial({ color:0x8f1414, emissive:0xc01818, emissiveIntensity:1.1, metalness:0.3, roughness:0.3 }),
  asphalt:   new THREE.MeshStandardMaterial({ map:asphaltTex, color:0xbdbdbd, roughness:0.96, metalness:0.0 }),
  grass:     new THREE.MeshStandardMaterial({ map:grassTex, color:0xa8c498, roughness:1.0 }),
  gravel:    new THREE.MeshStandardMaterial({ color:0x9a8d76, roughness:1.0 }),
  white:     new THREE.MeshStandardMaterial({ color:0xf2f4f6, roughness:0.75 }),
  yellow:    new THREE.MeshStandardMaterial({ color:0xe8c832, roughness:0.75 }),
  redCurb:   new THREE.MeshStandardMaterial({ color:0xb03030, roughness:0.8 }),
  concrete:  new THREE.MeshStandardMaterial({ color:0xb9bcc0, roughness:0.92 }),
  pole:      new THREE.MeshStandardMaterial({ color:0x3a4048, metalness:0.8, roughness:0.4 }),
  lampHead:  new THREE.MeshStandardMaterial({ color:0xfff2c8, emissive:0xffedb5, emissiveIntensity:0.9, roughness:0.4 }),
  black:     new THREE.MeshStandardMaterial({ color:0x101114, roughness:0.9 }),
  skid:      new THREE.MeshBasicMaterial({ color:0x0a0a0a, transparent:true, opacity:0.34, depthWrite:false, polygonOffset:true, polygonOffsetFactor:-1 }),
};
const brickMats = [0xffffff, 0xe8d5cc, 0xd8c2b8, 0xf2e2d8].map(tint =>
  new THREE.MeshStandardMaterial({ map:brickTex, color:tint, roughness:0.93, metalness:0.0 }));

/* permanent ground (grass) */
const grassMesh = new THREE.Mesh(new THREE.PlaneGeometry(320, 200), MAT.grass);
grassMesh.rotation.x = -Math.PI/2; grassMesh.position.y = -0.03; grassMesh.receiveShadow = true;
scene.add(grassMesh);

/* ================= playback / global sim state ================= */
const FIXED = 1/120, MAX_STEPS = 20;
let simSpeed = 1;              // survives Replay / Apply; first run = 1x
let playing = true;            // first run starts playing
let cameraMode = 'impact';     // survives Replay; first run = Impact
let accumulator = 0, simTime = 0;
let run = null;                // current run data, rebuilt by buildRun()

const $ = id => document.getElementById(id);
const hudStatus = $('hudStatus'), hudSpeed = $('hudSpeed'), hudTime = $('hudTime'), hudFps = $('hudFps'), hudBodies = $('hudBodies');

/* collision groups */
const G_GROUND = 1, G_CAR = 2, G_GLASS = 4, G_BRICK = 8, G_WHEEL = 16;

/* ================= run construction ================= */
function disposeGroup(gr){
  if (!gr) return;
  gr.traverse(o=>{ if (o.geometry) o.geometry.dispose(); });
  scene.remove(gr);
}

function buildRun(s){
  disposeGroup(run?.group);

  const group = new THREE.Group(); scene.add(group);
  const world = new CANNON.World({ gravity: new CANNON.Vec3(0, -s.gravity, 0) });
  world.broadphase = new CANNON.SAPBroadphase(world);
  world.allowSleep = true;
  world.solver.iterations = 14; world.solver.tolerance = 0.001;
  world.defaultContactMaterial.contactEquationStiffness = 1e7;
  world.defaultContactMaterial.contactEquationRelaxation = 3;
  world.defaultContactMaterial.frictionEquationStiffness = 1e7;

  const mGround = new CANNON.Material('ground'), mBrick = new CANNON.Material('brick'), mCar = new CANNON.Material('car');
  world.addContactMaterial(new CANNON.ContactMaterial(mGround, mBrick, { friction:s.groundFriction, restitution:s.brickRest }));
  world.addContactMaterial(new CANNON.ContactMaterial(mGround, mCar,   { friction:s.groundFriction, restitution:0.12 }));
  world.addContactMaterial(new CANNON.ContactMaterial(mBrick, mBrick,  { friction:s.brickFriction,  restitution:s.brickRest }));
  world.addContactMaterial(new CANNON.ContactMaterial(mBrick, mCar,    { friction:s.brickFriction,  restitution:s.brickRest }));
  world.addContactMaterial(new CANNON.ContactMaterial(mCar, mCar,      { friction:0.45, restitution:0.10 }));

  const R = {
    s, world, group, entries:[], joints:[], glassPanes:[], carBodies:[],
    brickIds:new Set(), peak:new Map(), shatterQueue:[],
    driving:true, impacted:false, settled:false, settleFrames:0,
    driveSpeed:0, shake:0, fxDone:false, simT:0, impactPoint:new THREE.Vector3(),
    prevCabinVel:new CANNON.Vec3(), skidL:null, skidR:null, skidStartX:0, wheelZ:0,
    dust:null, sparks:null,
  };
  run = R;
  simTime = 0; accumulator = 0;

  /* ---- sun shadow frustum tight on the track ---- */
  const TL = s.trackLength;
  sun.position.set(14, 26, 13); sun.target.position.set(2, 0, 0);
  const ext = TL * 0.62;
  Object.assign(sun.shadow.camera, { left:-ext, right:ext, top:ext*0.7, bottom:-ext*0.7, near:2, far:90 });
  sun.shadow.camera.updateProjectionMatrix();

  /* ---- static ground body ---- */
  const groundBody = new CANNON.Body({ mass:0, material:mGround, shape:new CANNON.Plane(), collisionFilterGroup:G_GROUND, collisionFilterMask:-1 });
  groundBody.quaternion.setFromEuler(-Math.PI/2, 0, 0);
  world.addBody(groundBody);

  const addStaticBox = (sx,sy,sz, x,y,z, mat, cast=false)=>{
    const m = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), mat);
    m.position.set(x,y,z); m.receiveShadow = true; m.castShadow = cast; group.add(m);
    const b = new CANNON.Body({ mass:0, material:mGround, shape:new CANNON.Box(new CANNON.Vec3(sx/2,sy/2,sz/2)), position:new CANNON.Vec3(x,y,z), collisionFilterGroup:G_GROUND, collisionFilterMask:-1 });
    world.addBody(b); return m;
  };
  const addVisualBox = (sx,sy,sz, x,y,z, mat, cast=false, recv=true)=>{
    const m = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), mat);
    m.position.set(x,y,z); m.castShadow = cast; m.receiveShadow = recv; group.add(m); return m;
  };

  /* ---- track: asphalt, shoulders, curbs, markings, barriers, lights ---- */
  const ROAD_W = 7.2;
  asphaltTex.repeat.set(TL/3.5, 2);
  addVisualBox(TL, 0.1, ROAD_W, 0, -0.05, 0, MAT.asphalt);
  addVisualBox(TL, 0.06, 2.0, 0, -0.03,  (ROAD_W/2 + 1.0), MAT.gravel);
  addVisualBox(TL, 0.06, 2.0, 0, -0.03, -(ROAD_W/2 + 1.0), MAT.gravel);
  // curbs (physical) + red segments (visual instancing)
  addStaticBox(TL, 0.11, 0.42, 0, 0.055,  (ROAD_W/2 + 0.21), MAT.white);
  addStaticBox(TL, 0.11, 0.42, 0, 0.055, -(ROAD_W/2 + 0.21), MAT.white);
  {
    const n = Math.floor(TL/2);
    const seg = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 0.115, 0.43), MAT.redCurb, n*2);
    const M = new THREE.Matrix4(); let k = 0;
    for (let i=0;i<n;i+=2){ const x = -TL/2 + i*2 + 0.5;
      M.setPosition(x, 0.056,  (ROAD_W/2+0.21)); seg.setMatrixAt(k++, M);
      M.setPosition(x, 0.056, -(ROAD_W/2+0.21)); seg.setMatrixAt(k++, M); }
    seg.count = k; seg.receiveShadow = true; group.add(seg);
  }
  // edge lines + center dashes (instanced) + start checker + warning stripe
  addVisualBox(TL, 0.012, 0.14, 0, 0.006,  (ROAD_W/2 - 0.35), MAT.white, false);
  addVisualBox(TL, 0.012, 0.14, 0, 0.006, -(ROAD_W/2 - 0.35), MAT.white, false);
  {
    const n = Math.floor(TL/3);
    const dash = new THREE.InstancedMesh(new THREE.BoxGeometry(1.6, 0.012, 0.16), MAT.white, n);
    const M = new THREE.Matrix4();
    for (let i=0;i<n;i++){ M.setPosition(-TL/2 + 1.5 + i*3, 0.006, 0); dash.setMatrixAt(i, M); }
    dash.receiveShadow = true; group.add(dash);
  }
  const startX = -TL/2 + 3 + s.carLength/2;
  {
    const cols = 10, sq = ROAD_W/cols;
    const chk = new THREE.InstancedMesh(new THREE.BoxGeometry(0.36, 0.012, sq), MAT.black, cols);
    const M = new THREE.Matrix4(); let k=0;
    for (let i=0;i<cols;i++) if (i%2===0){ M.setPosition(startX - s.carLength/2 - 0.6, 0.006, -ROAD_W/2 + sq*(i+0.5)); chk.setMatrixAt(k++, M); }
    chk.count = k; group.add(chk);
    addVisualBox(0.4, 0.011, ROAD_W, startX - s.carLength/2 - 0.6, 0.005, 0, MAT.white, false);
  }
  const wallX = TL/2 - 4.5;
  addVisualBox(0.35, 0.012, ROAD_W, wallX - 2.2, 0.006, 0, MAT.yellow, false);
  // concrete barriers flanking the wall zone + light poles
  for (const dz of [ROAD_W/2 + 1.6, -(ROAD_W/2 + 1.6)])
    for (const dx of [-4.5, 0, 4.5]) addStaticBox(3.6, 0.85, 0.5, wallX + dx, 0.425, dz, MAT.concrete, true);
  for (const px of [-TL/2 + 6, -TL/6, TL/6, wallX - 6]){
    for (const pz of [ROAD_W/2 + 2.6, -(ROAD_W/2 + 2.6)]){
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.09, 6.4, 8), MAT.pole);
      pole.position.set(px, 3.2, pz); pole.castShadow = true; group.add(pole);
      addVisualBox(0.9, 0.14, 0.34, px, 6.45, pz - Math.sign(pz)*0.5, MAT.lampHead, false, false);
    }
  }

  /* ---- brick wall: individual rigid bodies, staggered running bond ---- */
  const bw = s.brickW, bh = s.brickH, bd = s.brickD, gapZ = 0.02, gapY = 0.015, gapX = 0.015;
  const brickGeo = new THREE.BoxGeometry(bd, bh, bw);           // x=depth, y=height, z=width(→ across track)
  const brickShape = new CANNON.Box(new CANNON.Vec3(bd/2, bh/2, bw/2));
  for (let layer=0; layer<s.wallDepth; layer++){
    for (let row=0; row<s.wallRows; row++){
      const stagger = ((row + layer) % 2) ? (bw + gapZ)/2 : 0;
      for (let col=0; col<s.wallCols; col++){
        const z = (col - (s.wallCols-1)/2) * (bw + gapZ) + stagger - ((row+layer)%2 ? (bw+gapZ)/4 : 0);
        const y = bh/2 + row * (bh + gapY);
        const x = wallX + (layer - (s.wallDepth-1)/2) * (bd + gapX);
        const body = new CANNON.Body({ mass:s.brickMass, material:mBrick, shape:brickShape,
          position:new CANNON.Vec3(x,y,z), linearDamping:0.01, angularDamping:0.06,
          collisionFilterGroup:G_BRICK, collisionFilterMask:-1, allowSleep:true, sleepSpeedLimit:0.45, sleepTimeLimit:0.7 });
        world.addBody(body); body.sleep();
        const mesh = new THREE.Mesh(brickGeo, brickMats[(col*31 + row*17 + layer*7) % brickMats.length]);
        mesh.castShadow = mesh.receiveShadow = true; group.add(mesh);
        R.entries.push({ body, mesh, isBrick:true });
        R.brickIds.add(body.id);
        attachCollide(body);
      }
    }
  }
  R.wallX = wallX; R.startX = startX;
  R.wallFrontX = wallX - ((s.wallDepth-1)/2)*(bd+gapX) - bd/2;

  /* ================= car: separate rigid bodies, breakable joints ================= */
  const L = s.carLength, W = s.carWidth, H = s.carHeight;
  const wheelR = clamp(H*0.225, 0.26, 0.40), wheelWid = 0.24;
  const bodyBottom = 0.22, tubH = H*0.34, topY = bodyBottom + tubH, cabinH = H*0.44;

  // mass fractions, normalised so the assembled car is exactly s.carMass
  const FR = { tub:0.36, cabin:0.15, engine:0.11, nose:0.07, hood:0.030, trunk:0.025, door:0.020, bumperF:0.020, bumperR:0.020,
               roof:0.030, shield:0.015, rearGlass:0.012, sideGlass:0.006, wheel:0.026 };
  const frSum = FR.tub+FR.cabin+FR.engine+FR.nose+FR.hood+FR.trunk+FR.door*4+FR.bumperF+FR.bumperR+FR.roof+FR.shield+FR.rearGlass+FR.sideGlass*4+FR.wheel*4;
  const massOf = f => f/frSum * s.carMass;

  const P = {}; // named parts {body, mesh, entry}
  function addPart(name, size, local, mat, mass, opts={}){
    const geo = new THREE.BoxGeometry(size.x, size.y, size.z);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = mesh.receiveShadow = true; group.add(mesh);
    const body = new CANNON.Body({ mass, material:mCar,
      shape:new CANNON.Box(new CANNON.Vec3(size.x/2, size.y/2, size.z/2)),
      position:new CANNON.Vec3(startX + local.x, local.y, local.z),
      linearDamping:0.01, angularDamping:0.12, allowSleep:false,
      collisionFilterGroup:opts.group ?? G_CAR, collisionFilterMask:opts.mask ?? -1 });
    if (opts.rotZ) body.quaternion.setFromEuler(0, 0, opts.rotZ);
    world.addBody(body); attachCollide(body);
    const entry = { body, mesh, isCar:true, size:{...size}, name };
    R.entries.push(entry); R.carBodies.push(body);
    P[name] = { body, mesh, entry };
    return P[name];
  }
  const child = (parentMesh, sx,sy,sz, x,y,z, mat)=>{
    const m = new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz), mat);
    m.position.set(x,y,z); m.castShadow = m.receiveShadow = true; parentMesh.add(m); return m;
  };

  // chassis tub (rear structure) + cabin + front clip in two crumple segments
  const tubLen = 0.58*L;
  addPart('tub',    {x:tubLen, y:tubH, z:0.94*W}, {x:-0.19*L, y:bodyBottom + tubH/2, z:0}, MAT.paint, massOf(FR.tub));
  const tubFrontX = -0.19*L + tubLen/2;
  const engLen = 0.24*L, engH = tubH*0.95;
  addPart('engine', {x:engLen, y:engH, z:0.92*W}, {x:tubFrontX + 0.015 + engLen/2, y:topY - engH/2, z:0}, MAT.paint, massOf(FR.engine));
  const engFrontX = tubFrontX + 0.015 + engLen;
  const noseLen = 0.15*L, noseH = tubH*0.8;
  addPart('nose',   {x:noseLen, y:noseH, z:0.90*W}, {x:engFrontX + 0.015 + noseLen/2, y:topY - noseH/2 - 0.01, z:0}, MAT.paint, massOf(FR.nose));
  addPart('cabin',  {x:0.46*L, y:cabinH, z:0.86*W}, {x:-0.10*L, y:topY + 0.006 + cabinH/2, z:0}, MAT.interior, massOf(FR.cabin));
  // cabin pillars (visual, ride with cabin)
  for (const px of [0.46*L/2 - 0.045, -0.46*L/2 + 0.045]) for (const pz of [0.86*W/2 - 0.04, -0.86*W/2 + 0.04])
    child(P.cabin.mesh, 0.09, cabinH, 0.08, px, 0, pz, MAT.paint);
  child(P.tub.mesh, tubLen*0.98, 0.05, 0.9*W, 0, -tubH/2 + 0.025, 0, MAT.paintDark); // underbody tray
  // nose details: headlights + grille (ride with nose)
  for (const hz of [0.32*W, -0.32*W]) child(P.nose.mesh, 0.05, 0.11, 0.34, noseLen/2 + 0.012, noseH*0.12, hz, MAT.headlight);
  child(P.nose.mesh, 0.04, 0.16, 0.5*W, noseLen/2 + 0.01, -noseH*0.1, 0, MAT.paintDark);
  for (const hz of [0.32*W, -0.32*W]) child(P.tub.mesh, 0.05, 0.1, 0.3, -tubLen/2 - 0.012, tubH*0.1, hz, MAT.taillight);

  addPart('roof',  {x:0.42*L, y:0.07, z:0.82*W}, {x:-0.10*L, y:topY + cabinH + 0.045, z:0}, MAT.paint, massOf(FR.roof));
  addPart('hood',  {x:0.36*L, y:0.045, z:0.84*W}, {x:0.28*L, y:topY + 0.034, z:0}, MAT.paint, massOf(FR.hood));
  addPart('trunk', {x:0.22*L, y:0.045, z:0.84*W}, {x:-0.36*L, y:topY + 0.034, z:0}, MAT.paint, massOf(FR.trunk));
  addPart('bumperF', {x:0.13, y:0.17*H, z:0.96*W}, {x:L/2 + 0.045, y:0.30*H, z:0}, MAT.paintDark, massOf(FR.bumperF));
  addPart('bumperR', {x:0.13, y:0.17*H, z:0.96*W}, {x:-L/2 - 0.045, y:0.30*H, z:0}, MAT.paintDark, massOf(FR.bumperR));

  // doors (hinge + latch) — front & rear, both sides
  const doorLen = 0.23*L, doorH = H*0.42, doorY = bodyBottom + doorH/2 + 0.01, doorZ = 0.47*W + 0.035;
  const doorDefs = [
    ['doorFL',  0.085*L,  doorZ], ['doorFR',  0.085*L, -doorZ],
    ['doorRL', -0.175*L,  doorZ], ['doorRR', -0.175*L, -doorZ],
  ];
  for (const [nm, dx, dz] of doorDefs){
    addPart(nm, {x:doorLen, y:doorH, z:0.06}, {x:dx, y:doorY, z:dz}, MAT.paint, massOf(FR.door));
    child(P[nm].mesh, doorLen*0.7, 0.035, 0.02, -doorLen*0.08, doorH*0.28, Math.sign(dz)*0.04, MAT.chrome); // handle strip
  }

  // glass panes (pre-shatter bodies; collide with bricks/ground, not own bodywork)
  const glassMask = G_GROUND | G_BRICK | G_GLASS;
  const shield = addPart('shield', {x:0.03, y:cabinH*0.95, z:0.78*W}, {x:0.165*L, y:topY + cabinH*0.52, z:0}, MAT.glass, massOf(FR.shield), { group:G_GLASS, mask:glassMask, rotZ:-0.45 });
  const rearGl = addPart('rearGlass', {x:0.03, y:cabinH*0.9, z:0.78*W}, {x:-0.355*L, y:topY + cabinH*0.52, z:0}, MAT.glass, massOf(FR.rearGlass), { group:G_GLASS, mask:glassMask, rotZ:0.45 });
  R.glassPanes.push(shield.entry, rearGl.entry);
  const sgDefs = [['sgFL',0.085*L],['sgFR',0.085*L],['sgRL',-0.175*L],['sgRR',-0.175*L]];
  sgDefs.forEach(([nm, dx], i)=>{
    const dz = (i%2===0 ? 1 : -1) * (0.43*W + 0.02);
    const p = addPart(nm, {x:0.20*L, y:cabinH*0.72, z:0.03}, {x:dx, y:topY + cabinH*0.55, z:dz}, MAT.glass, massOf(FR.sideGlass), { group:G_GLASS, mask:glassMask });
    R.glassPanes.push(p.entry);
  });

  // wheels: cannon cylinder axis is Z (= axle axis); three cylinder rotated to match
  const wheelShape = new CANNON.Cylinder(wheelR, wheelR, wheelWid, 14);
  const tireGeo = new THREE.CylinderGeometry(wheelR, wheelR, wheelWid, 22); tireGeo.rotateX(Math.PI/2);
  const rimGeo  = new THREE.CylinderGeometry(wheelR*0.56, wheelR*0.56, wheelWid + 0.012, 18); rimGeo.rotateX(Math.PI/2);
  const hubGeo  = new THREE.CylinderGeometry(wheelR*0.16, wheelR*0.16, wheelWid + 0.03, 10); hubGeo.rotateX(Math.PI/2);
  const wheelZ = W/2 - wheelWid/2 + 0.02; R.wheelZ = wheelZ;
  const wheelDefs = [
    ['wheelFL',  0.30*L,  wheelZ, 'engine'], ['wheelFR',  0.30*L, -wheelZ, 'engine'],
    ['wheelRL', -0.32*L,  wheelZ, 'tub'],    ['wheelRR', -0.32*L, -wheelZ, 'tub'],
  ];
  for (const [nm, dx, dz] of wheelDefs){
    const g = new THREE.Group();
    const tire = new THREE.Mesh(tireGeo, MAT.tire); tire.castShadow = tire.receiveShadow = true;
    const rim  = new THREE.Mesh(rimGeo, MAT.rim);   rim.castShadow = true;
    const hub  = new THREE.Mesh(hubGeo, MAT.chrome);
    g.add(tire, rim, hub); group.add(g);
    const body = new CANNON.Body({ mass:massOf(FR.wheel), material:mCar, shape:wheelShape,
      position:new CANNON.Vec3(startX + dx, wheelR, dz), linearDamping:0.01, angularDamping:0.04, allowSleep:false,
      collisionFilterGroup:G_WHEEL, collisionFilterMask:G_GROUND | G_BRICK | G_WHEEL });
    world.addBody(body); attachCollide(body);
    const entry = { body, mesh:g, isCar:true, isWheel:true, name:nm };
    R.entries.push(entry); R.carBodies.push(body);
    P[nm] = { body, mesh:g, entry };
  }
  R.parts = P; R.cabin = P.cabin.body; R.nose = P.nose.body; R.wheelR = wheelR;
  R.prevCabinVel.set(0,0,0);

  /* ---- breakable joints ---- */
  const V3 = (x,y,z)=>new CANNON.Vec3(x,y,z);
  function restRel(a, b){ const d = b.position.vsub(a.position); const q = new CANNON.Quaternion(); a.quaternion.conjugate(q); return q.vmult(d); }
  function lock(a, b, o){
    const c = new CANNON.LockConstraint(a, b, { maxForce: o.maxForce ?? 1e7 });
    world.addConstraint(c);
    R.joints.push({ c, a, b, kind:'lock', rest:restRel(a,b), breakDist:o.breakDist, velThr:o.velThr, decelThr:o.decelThr ?? null, onBreak:o.onBreak || null, dead:false });
  }
  function hinge(a, b, pivotWorld, axis, o){
    const pA = pivotWorld.vsub(a.position), pB = pivotWorld.vsub(b.position);
    const c = new CANNON.HingeConstraint(a, b, { pivotA:pA, axisA:axis, pivotB:pB, axisB:axis, maxForce:o.maxForce ?? 1e6, collideConnected:false });
    world.addConstraint(c);
    R.joints.push({ c, a, b, kind:'hinge', pA, pB, breakDist:o.breakDist, velThr:o.velThr, decelThr:o.decelThr ?? null, onBreak:o.onBreak || null, dead:false });
  }
  const wp = (lx, y, z)=>V3(startX + lx, y, z); // world point from car-local x

  lock(P.tub.body, P.cabin.body,  { breakDist:0.20, velThr:9.0 });
  lock(P.cabin.body, P.roof.body, { breakDist:0.12, velThr:6.0, decelThr:0.65 });
  lock(P.tub.body, P.engine.body, { breakDist:0.18, velThr:7.0 });                    // front clip ↔ cabin structure
  lock(P.engine.body, P.nose.body,{ breakDist:0.12, velThr:4.5 });                    // crumple segment joint
  lock(P.nose.body, P.bumperF.body, { breakDist:0.10, velThr:3.5, decelThr:0.3 });
  lock(P.tub.body, P.bumperR.body,  { breakDist:0.10, velThr:4.5 });
  // hood: rear hinge + front latch (latch breaks first → hood flips)
  hinge(P.engine.body, P.hood.body, wp(0.28*L - 0.18*L, topY + 0.034, 0), V3(0,0,1), { breakDist:0.22, velThr:7.0 });
  lock(P.nose.body, P.hood.body, { breakDist:0.08, velThr:4.0, decelThr:0.3 });
  // trunk: front hinge + rear latch
  hinge(P.tub.body, P.trunk.body, wp(-0.36*L + 0.11*L, topY + 0.034, 0), V3(0,0,1), { breakDist:0.22, velThr:7.0 });
  lock(P.tub.body, P.trunk.body, { breakDist:0.08, velThr:5.0, decelThr:0.45 });
  // doors: front-edge hinge + latch (latch breaks → door swings; hinge breaks → tears off)
  for (const [nm, dx, dz] of doorDefs){
    hinge(P.tub.body, P[nm].body, wp(dx + doorLen/2, doorY, dz), V3(0,1,0), { breakDist:0.24, velThr:8.0 });
    lock(P.tub.body, P[nm].body, { breakDist:0.08, velThr:4.5, decelThr:0.3 });
  }
  // glass held to cabin; breaking shatters the pane into shard bodies
  for (const pane of R.glassPanes)
    lock(P.cabin.body, pane.body, { breakDist:0.06, velThr:3.0, maxForce:1e6, onBreak:()=>queueShatter(pane) });
  // wheels on axle hinges; a detached wheel then collides with everything
  for (const [nm, dx, dz, host] of wheelDefs){
    const wb = P[nm].body;
    hinge(P[host].body, wb, V3(wb.position.x, wb.position.y, wb.position.z), V3(0,0,1),
      { breakDist:0.25, velThr:8.5, maxForce:1e6, onBreak:()=>{ wb.collisionFilterMask = -1; wb.wakeUp(); } });
  }

  /* ---- skid marks (visual) ---- */
  const skidGeo = new THREE.PlaneGeometry(1, 0.17); skidGeo.rotateX(-Math.PI/2);
  for (const side of ['skidL','skidR']){
    const m = new THREE.Mesh(skidGeo, MAT.skid);
    m.position.set(startX, 0.008, side==='skidL' ? wheelZ : -wheelZ); m.scale.x = 0.1; m.renderOrder = 1;
    group.add(m); R[side] = m;
  }
  R.skidStartX = startX - 0.32*L;

  /* ---- dust + sparks (visual only, seeded) ---- */
  R.dust = makeParticles(260, 0xcbb astonishing => 0, 0); // replaced below (kept simple)
  R.dust = makeParticleCloud(260, { color:0xc9b48f, size:0.42, opacity:0.0, additive:false });
  R.sparks = makeParticleCloud(90, { color:0xffb347, size:0.09, opacity:0.0, additive:true });
  group.add(R.dust.points, R.sparks.points);

  /* ---- drive profile: reach target speed before the wall ---- */
  const noseStartX = startX + L/2;
  const runDist = Math.max(4, R.wallFrontX - noseStartX);
  R.accel = clamp((s.speed*s.speed) / (2 * runDist * 0.65), 6, 42);
  R.driveSpeed = Math.min(s.speed * 0.3, 6);
  for (const b of R.carBodies) b.velocity.set(R.driveSpeed, 0, 0);

  /* ---- camera snap for the fresh run (mode itself persists) ---- */
  snapCameraForRun();
  playing = true; updatePlayBtn();
  hudStatus.textContent = 'Driving';
  hudBodies.textContent = String(world.bodies.length);
}

function makeParticles(){ return null; }
function makeParticleCloud(n, { color, size, opacity, additive }){
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n*3), 3));
  const mat = new THREE.PointsMaterial({ color, size, transparent:true, opacity, depthWrite:false,
    blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending, sizeAttenuation:true });
  const points = new THREE.Points(geo, mat); points.frustumCulled = false; points.visible = false;
  return { points, geo, mat, vel:new Float32Array(n*3), life:0, maxLife:1, n, active:false };
}
function burstParticles(cloud, origin, seed, spread, up, life){
  const rng = mulberry32(seed);
  const pos = cloud.geo.attributes.position.array;
  for (let i=0;i<cloud.n;i++){
    pos[i*3] = origin.x + (rng()-0.5)*1.2; pos[i*3+1] = Math.max(0.08, origin.y + (rng()-0.5)*1.4); pos[i*3+2] = origin.z + (rng()-0.5)*2.4;
    cloud.vel[i*3] = (rng()-0.35)*spread; cloud.vel[i*3+1] = rng()*up; cloud.vel[i*3+2] = (rng()-0.5)*spread*1.4;
  }
  cloud.geo.attributes.position.needsUpdate = true;
  cloud.life = cloud.maxLife = life; cloud.active = true; cloud.points.visible = true;
}
function updateParticles(cloud, dt, drag, grav, baseOpacity){
  if (!cloud || !cloud.active) return;
  cloud.life -= dt;
  if (cloud.life <= 0){ cloud.active = false; cloud.points.visible = false; cloud.mat.opacity = 0; return; }
  const pos = cloud.geo.attributes.position.array, k = Math.max(0, 1 - drag*dt);
  for (let i=0;i<cloud.n;i++){
    cloud.vel[i*3] *= k; cloud.vel[i*3+2] *= k; cloud.vel[i*3+1] = cloud.vel[i*3+1]*k - grav*dt;
    pos[i*3] += cloud.vel[i*3]*dt; pos[i*3+1] = Math.max(0.04, pos[i*3+1] + cloud.vel[i*3+1]*dt); pos[i*3+2] += cloud.vel[i*3+2]*dt;
  }
  cloud.geo.attributes.position.needsUpdate = true;
  cloud.mat.opacity = baseOpacity * (cloud.life / cloud.maxLife);
}

/* ================= collision bookkeeping ================= */
function attachCollide(body){
  body.addEventListener('collide', e=>{
    if (!run) return;
    const v = Math.abs(e.contact.getImpactVelocityAlongNormal());
    if (v > (run.peak.get(body.id) || 0)) run.peak.set(body.id, v);
    const other = e.body;
    if (!run.impacted && v > 2.0){
      const carHitBrick = (run.brickIds.has(body.id) && !run.brickIds.has(other.id)) ||
                          (run.brickIds.has(other.id) && !run.brickIds.has(body.id));
      if (carHitBrick) triggerImpact();
    }
  });
}
function triggerImpact(){
  if (run.impacted) return;
  run.impacted = true; run.driving = false;
  run.impactPoint.set(run.nose.position.x, run.nose.position.y, run.nose.position.z);
  run.shake = 1.0;
  for (const b of run.carBodies){ b.allowSleep = true; b.sleepSpeedLimit = 0.5; b.sleepTimeLimit = 0.8; b.wakeUp(); }
  burstParticles(run.dust, run.impactPoint, 4242, 5.5, 3.2, 2.6);
  burstParticles(run.sparks, run.impactPoint, 777, 9.0, 4.5, 0.55);
  hudStatus.textContent = 'Impact';
}

/* ================= glass shattering ================= */
const SHARD_SPREAD = [[-0.5,0.4,-0.3],[0.4,0.7,0.3],[-0.2,1.0,0.5],[0.6,0.2,-0.5],[-0.6,0.8,0.1],[0.1,0.5,-0.6],[0.3,0.9,0.6],[-0.4,0.3,0.4]];
function queueShatter(pane){ if (!pane.shattered && !pane.dead) run.shatterQueue.push(pane); }
function doShatter(pane){
  if (pane.shattered || pane.dead) return;
  pane.shattered = true;
  const { world, group } = run;
  const body = pane.body, size = pane.size;
  const cols = 3, rows = 2, n = cols*rows;
  const shardMass = Math.max(0.05, body.mass / n);
  // shard local axes: use the two largest pane dims as the grid plane
  const dims = [['x',size.x],['y',size.y],['z',size.z]].sort((a,b)=>b[1]-a[1]);
  const thin = dims[2][0];
  const shardSize = { x:size.x, y:size.y, z:size.z };
  shardSize[dims[0][0]] /= cols; shardSize[dims[1][0]] /= rows;
  for (const k in shardSize) shardSize[k] = Math.max(0.012, shardSize[k]*0.92);
  const geo = new THREE.BoxGeometry(shardSize.x, shardSize.y, shardSize.z);
  const shape = new CANNON.Box(new CANNON.Vec3(shardSize.x/2, shardSize.y/2, shardSize.z/2));
  let idx = 0;
  for (let i=0;i<cols;i++) for (let j=0;j<rows;j++, idx++){
    const local = new CANNON.Vec3();
    local[dims[0][0]] = (i - (cols-1)/2) * (size[dims[0][0]]/cols);
    local[dims[1][0]] = (j - (rows-1)/2) * (size[dims[1][0]]/rows);
    local[thin] = 0;
    const wpv = body.pointToWorldFrame(local);
    const sb = new CANNON.Body({ mass:shardMass, shape, position:wpv, material:body.material,
      linearDamping:0.01, angularDamping:0.05, allowSleep:true, sleepSpeedLimit:0.5, sleepTimeLimit:0.7,
      collisionFilterGroup:G_CAR, collisionFilterMask:-1 });
    sb.quaternion.copy(body.quaternion);
    const sp = SHARD_SPREAD[idx % SHARD_SPREAD.length];
    sb.velocity.set(body.velocity.x + sp[0], body.velocity.y + sp[1], body.velocity.z + sp[2]);
    sb.angularVelocity.set(body.angularVelocity.x + sp[2]*2, body.angularVelocity.y + sp[0]*2, body.angularVelocity.z + sp[1]);
    world.addBody(sb); attachCollide(sb);
    const mesh = new THREE.Mesh(geo, MAT.glass); mesh.castShadow = mesh.receiveShadow = true; group.add(mesh);
    run.entries.push({ body:sb, mesh, isCar:true, isShard:true });
    run.carBodies.push(sb);
  }
  // remove the intact pane and any joints still holding it
  for (const j of run.joints) if (!j.dead && (j.a === body || j.b === body)){ world.removeConstraint(j.c); j.dead = true; }
  world.removeBody(body);
  group.remove(pane.mesh); pane.mesh.geometry.dispose();
  pane.dead = true;
  hudBodies.textContent = String(world.bodies.length);
}

/* ================= physics stepping ================= */
const _qc = new CANNON.Quaternion(), _tmpA = new CANNON.Vec3(), _tmpB = new CANNON.Vec3(), _tmpC = new CANNON.Vec3();
function breakJoint(j){
  j.dead = true; run.world.removeConstraint(j.c);
  j.a.wakeUp(); j.b.wakeUp();
  if (j.onBreak) j.onBreak();
}
function stepPhysics(dt){
  const R = run, s = R.s;
  // approach drive: hold the assembled car at the ramping drive speed until contact
  if (R.driving){
    R.driveSpeed = Math.min(s.speed, R.driveSpeed + R.accel*dt);
    for (const e of R.entries){
      if (!e.isCar || e.dead) continue;
      const b = e.body; b.wakeUp();
      b.velocity.x = R.driveSpeed; b.velocity.z *= 0.6;
      if (e.isWheel) b.angularVelocity.set(0, 0, -R.driveSpeed / R.wheelR);
      else { b.angularVelocity.x *= 0.6; b.angularVelocity.y *= 0.6; b.angularVelocity.z *= 0.6; }
    }
  }
  R.world.step(dt);
  R.simT += dt; simTime = R.simT;

  // failsafe: nose reached the wall face even if a contact event was missed
  if (!R.impacted && R.nose.position.x + 0.05 >= R.wallFrontX) triggerImpact();

  // cabin deceleration spike (inertia) breaks latches and can shatter glass
  const dv = R.cabin.velocity.vsub(R.prevCabinVel, _tmpC).length();
  R.prevCabinVel.copy(R.cabin.velocity);
  if (R.impacted && dv > 0.45) for (const pane of R.glassPanes) queueShatter(pane);

  // breakable joints: strain, per-body impact velocity, or cabin-decel thresholds
  for (const j of R.joints){
    if (j.dead) continue;
    let strain;
    if (j.kind === 'lock'){
      j.b.position.vsub(j.a.position, _tmpA);
      j.a.quaternion.conjugate(_qc); _qc.vmult(_tmpA, _tmpB);
      strain = _tmpB.distanceTo(j.rest);
    } else {
      j.a.pointToWorldFrame(j.pA, _tmpA); j.b.pointToWorldFrame(j.pB, _tmpB);
      strain = _tmpA.distanceTo(_tmpB);
    }
    const peakHit = Math.max(R.peak.get(j.a.id)||0, R.peak.get(j.b.id)||0) > j.velThr;
    const decelHit = j.decelThr !== null && R.impacted && dv > j.decelThr;
    if (strain > j.breakDist || peakHit || decelHit) breakJoint(j);
  }
  // glass panes also shatter on their own hard contact
  for (const pane of R.glassPanes)
    if ((R.peak.get(pane.body.id)||0) > 3.2) queueShatter(pane);
  while (R.shatterQueue.length) doShatter(R.shatterQueue.pop());
  R.peak.clear();
}

/* ================= cameras ================= */
const camPosSmooth = new THREE.Vector3().copy(camera.position);
const camTgtSmooth = new THREE.Vector3(0, 1, 0);
const _v1 = new THREE.Vector3(), _v2 = new THREE.Vector3(), _v3 = new THREE.Vector3(), _fwd = new THREE.Vector3(), _rgt = new THREE.Vector3();
function cabinPos(out){ const p = run.cabin.position; return out.set(p.x, p.y, p.z); }
function snapCameraForRun(){
  const R = run; cabinPos(_v1);
  if (cameraMode === 'impact'){
    camera.up.set(0,1,0);
    camPosSmooth.set(R.startX + (R.wallX - R.startX)*0.35, 9.5, 17);
    camTgtSmooth.set((R.startX + R.wallX)/2, 1, 0);
  } else if (cameraMode === 'follow'){
    camera.up.set(0,1,0);
    camPosSmooth.set(_v1.x - 8, _v1.y + 3, _v1.z + 3);
    camTgtSmooth.copy(_v1);
  } else if (cameraMode === 'top'){
    camera.up.set(0,0,-1);
    camPosSmooth.set(_v1.x, 32, 0.01); camTgtSmooth.set(_v1.x, 0, 0);
  } else {
    camera.up.set(0,1,0);
    controls.target.copy(_v1);
    camPosSmooth.copy(camera.position); camTgtSmooth.copy(_v1);
  }
  camera.position.copy(camPosSmooth); camera.lookAt(camTgtSmooth);
}
function updateCamera(dtReal){
  const R = run; if (!R) return;
  const kPos = 1 - Math.exp(-3.2*dtReal), kTgt = 1 - Math.exp(-5.0*dtReal);
  cabinPos(_v1);
  if (cameraMode === 'orbit'){
    controls.target.lerp(_v1, 0.04); controls.update();
    camPosSmooth.copy(camera.position); camTgtSmooth.copy(controls.target);
    return;
  }
  if (cameraMode === 'impact'){
    camera.up.set(0,1,0);
    const p = smooth01((_v1.x - R.startX) / Math.max(1, R.wallX - R.startX));
    _v2.set(R.startX + (R.wallX - R.startX)*0.35, 9.5, 17).lerp(_v3.set(R.wallX - 10.5, 4.2, 9.2), p);
    if (R.impacted) _v2.lerp(_v3.set(_v1.x - 6.5, 3.1, 7.2), 0.55);
    camPosSmooth.lerp(_v2, kPos);
    _v2.copy(_v1).lerp(_v3.set(R.wallX, 1.1, 0), R.impacted ? 0.08 : 0.35);
    camTgtSmooth.lerp(_v2, kTgt);
  } else if (cameraMode === 'follow'){
    camera.up.set(0,1,0);
    _fwd.set(1,0,0).applyQuaternion(_qFromCannon(R.cabin)); _fwd.y = 0;
    if (_fwd.lengthSq() < 1e-4) _fwd.set(1,0,0); _fwd.normalize();
    _rgt.set(-_fwd.z, 0, _fwd.x);
    _v2.copy(_v1).addScaledVector(_fwd, -8.2).addScaledVector(_rgt, 2.6); _v2.y = Math.max(1.4, _v1.y + 2.9);
    camPosSmooth.lerp(_v2, 1 - Math.exp(-4.5*dtReal));
    _v2.copy(_v1).addScaledVector(_fwd, 3.5);
    camTgtSmooth.lerp(_v2, kTgt);
  } else { // top
    camera.up.set(0,0,-1);
    const tx = clamp(_v1.x, R.startX, R.wallX + 3);
    _v2.set(tx, 32, 0.01); camPosSmooth.lerp(_v2, kPos);
    _v2.set(tx, 0, 0); camTgtSmooth.lerp(_v2, kTgt);
  }
  camera.position.copy(camPosSmooth);
  // brief impact shake (visual only; deterministic oscillation, never touches physics)
  if (R.shake > 0.001){
    const t = performance.now()*0.001, a = R.shake * (cameraMode==='top' ? 0.05 : 0.16);
    camera.position.x += Math.sin(t*61.3)*a; camera.position.y += Math.sin(t*53.7+1.3)*a*0.7; camera.position.z += Math.cos(t*47.9)*a;
    R.shake *= Math.exp(-3.4*dtReal);
  }
  camera.lookAt(camTgtSmooth);
}
const _q = new THREE.Quaternion();
function _qFromCannon(b){ return _q.set(b.quaternion.x, b.quaternion.y, b.quaternion.z, b.quaternion.w); }

/* ================= UI wiring ================= */
function updatePlayBtn(){ $('btnPlay').textContent = playing ? '❚❚ Pause' : '▶ Play'; }
function togglePlay(){ playing = !playing; updatePlayBtn(); }
$('btnPlay').addEventListener('click', togglePlay);
$('btnReplay').addEventListener('click', ()=>buildRun(readSettings()));
$('btnApply').addEventListener('click', ()=>buildRun(readSettings()));
$('btnDefaults').addEventListener('click', ()=>{ fillSettings(DEFAULTS); buildRun(readSettings()); });
$('btnSettings').addEventListener('click', ()=>$('panel').classList.toggle('hidden'));
document.querySelectorAll('[data-speed]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    simSpeed = parseFloat(btn.dataset.speed);
    document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('on', b===btn));
  });
});
document.querySelectorAll('[data-cam]').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    cameraMode = btn.dataset.cam;
    document.querySelectorAll('[data-cam]').forEach(b=>b.classList.toggle('on', b===btn));
    controls.enabled = (cameraMode === 'orbit');
    if (cameraMode === 'orbit' && run){ camera.up.set(0,1,0); controls.target.copy(camTgtSmooth); }
    if (cameraMode !== 'top') camera.up.set(0,1,0);
  });
});
window.addEventListener('keydown', e=>{
  if (e.code !== 'Space') return;
  const a = document.activeElement;
  if (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.tagName === 'SELECT')) return; // number input focused
  e.preventDefault();
  if (a && a.tagName === 'BUTTON') a.blur();
  togglePlay();
});
window.addEventListener('resize', ()=>{
  camera.aspect = innerWidth/innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

/* ================= main loop ================= */
let lastNow = performance.now(), fpsEMA = 60, hudTick = 0;
function animate(){
  requestAnimationFrame(animate);
  const now = performance.now();
  const dtReal = Math.min(0.05, (now - lastNow)/1000); lastNow = now;
  if (dtReal > 0) fpsEMA += ((1/dtReal) - fpsEMA) * 0.05;

  if (run && playing){
    accumulator += dtReal * simSpeed;
    let steps = 0;
    while (accumulator >= FIXED && steps < MAX_STEPS){ stepPhysics(FIXED); accumulator -= FIXED; steps++; }
    if (steps === MAX_STEPS) accumulator = 0; // drop backlog: a hitch can never explode the solver
  }
  const dtVis = playing ? dtReal * simSpeed : 0;

  if (run){
    for (const e of run.entries){
      if (e.dead) continue;
      e.mesh.position.copy(e.body.position);
      e.mesh.quaternion.copy(e.body.quaternion);
    }
    // skid marks grow while driving, freeze at impact
    if (run.driving && run.parts){
      const rx = (run.parts.wheelRL.body.position.x + run.parts.wheelRR.body.position.x)/2;
      const len = Math.max(0.1, rx - run.skidStartX);
      for (const m of [run.skidL, run.skidR]){ m.scale.x = len; m.position.x = run.skidStartX + len/2; }
    }
    updateParticles(run.dust, dtVis, 1.6, 0.6, 0.5);
    updateParticles(run.sparks, dtVis, 0.4, 6.0, 0.95);
    // settled detection: hold on the wreck
    if (run.impacted && !run.settled){
      let mx = 0;
      for (const b of run.carBodies) mx = Math.max(mx, b.velocity.length());
      if (mx < 0.35){ if (++run.settleFrames > 50){ run.settled = true; hudStatus.textContent = 'Settled — Replay for another run'; } }
      else run.settleFrames = 0;
    }
    if ((hudTick++ & 7) === 0){
      hudSpeed.textContent = (run.cabin.velocity.length()*3.6).toFixed(0);
      hudTime.textContent = simTime.toFixed(2);
      hudFps.textContent = fpsEMA.toFixed(0);
    }
  }
  updateCamera(dtReal);
  renderer.render(scene, camera);
}

/* first automatic run: mandatory defaults, 1x, playing, Impact camera — no click required */
buildRun(readSettings());
animate();
</script>
